import { defineConfig } from 'vitest/config';
import { swcTransform } from './vitest.transform';

/**
 * Unit tests: no database, no network, no Nest bootstrap.
 *
 * These run in CI on every commit and must stay fast enough that nobody is
 * tempted to skip them. Anything that needs PostgreSQL belongs in
 * `vitest.integration.config.ts`.
 *
 * `src/generated/prisma` is excluded because it is regenerated by
 * `npm run db:generate`; running tests before generating would otherwise fail
 * on a missing client rather than on a real defect.
 */
export default defineConfig({
  // SWC rather than esbuild: see vitest.transform.ts for why decorator metadata
  // is mandatory for Nest's dependency injection.
  plugins: [swcTransform()],
  test: {
    globals: false,
    environment: 'node',
    include: ['src/**/*.spec.ts'],
    exclude: [
      'node_modules/**',
      'dist/**',
      'src/generated/**',
      'test/**/*.e2e-spec.ts',
      'test/**/*.integration-spec.ts',
    ],
  },
});